import { type ReactNode, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import {
  Activity, ArrowDownToLine, ArrowRight, BarChart3, Check, CircleHelp,
  Clock3, Cpu, Database, Download, Eye, FileUp, Gauge, GitCompareArrows, Layers3, LayoutDashboard, ListTree,
  MessageSquare, MonitorDot, Play, Plus, Radio, RefreshCw, Search, Share2, SlidersHorizontal,
  Sparkles, Trash2, Upload, X,
} from 'lucide-react';
