const queryClient = new QueryClient();
const pretty = (v: unknown) => typeof v === 'number' ? Number(v).toFixed(2) : '—';
const dateLabel = (v?: string) => v ? new Date(v).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : '—';
const titleCase = (v?: string) => (v || '').replaceAll('-', ' ').replace(/\b\w/g, c => c.toUpperCase());
type RecommendationObjective = 'balanced'|'waiting'|'turnaround'|'response';
const IconMark = () => <div className="brand-mark"><span/><span/><span/><span/></div>;

function Shell({ children }: { children: ReactNode }) {
  const [path] = useLocation();
  const links = [
    { href: '/', name: 'Overview', icon: LayoutDashboard },
    { href: '/simulator', name: 'Simulator', icon: GitCompareArrows },
    { href: '/analytics', name: 'Analytics', icon: BarChart3 },
    { href: '/community', name: 'Community', icon: MessageSquare },
  ];
  return <div className="app-shell">
    <aside className="sidebar">
      <Link href="/" className="brand" data-testid="link-brand"><IconMark/><span className="brand-name">adaptive<span>OS</span><small>RESEARCH WORKBENCH</small></span></Link>
      <div className="nav-section-label">WORKSPACE</div>
      <nav className="side-nav">{links.map(({ href, name, icon: Icon }) => <Link key={href} href={href} className={`nav-link ${path === href ? 'active' : ''}`} data-testid={`link-nav-${name.toLowerCase()}`}><Icon size={17}/><span className="nav-label">{name}</span>{name === 'Simulator' && <span className="nav-count">01</span>}</Link>)}</nav>
      <div className="sidebar-spacer"/>
      <div className="side-agent"><div className="side-agent-head"><span className="live-dot"/> LOCAL AGENT</div><div className="side-agent-copy">Observe your machine<br/>with explicit opt-in.</div><Link href="/simulator" className="agent-link" data-testid="link-agent-settings">Agent settings <ArrowRight size={13}/></Link></div>
      <div className="side-meta"><span>ADAPTIVEOS</span><span className="mono">v0.1.0</span></div>
    </aside>
    <main className="main-area">
      <header className="topbar mobile-top"><div className="topbar-label"><IconMark/> AdaptiveOS</div><div className="topbar-status"><span className="live-dot"/> Workbench</div></header>
      <div className="topbar desktop-top"><div className="breadcrumb"><span>RESEARCH SPACE</span><span className="crumb-slash">/</span><span>{links.find(l => l.href === path)?.name.toUpperCase() || 'WORKSPACE'}</span></div><div className="topbar-right"><span className="connection"><span className="live-dot"/> API connected</span><span className="top-divider"/><span className="user-badge">OS</span><span className="top-user">Student workspace</span></div></div>
      {children}
    </main>
  </div>;
}

function PageHeading({ kicker, title, subtitle, actions }: { kicker: string; title: string; subtitle: string; actions?: ReactNode }) {
  return <div className="page-heading fade-in"><div><div className="eyebrow">{kicker}</div><h1>{title}</h1><p>{subtitle}</p></div>{actions && <div className="heading-actions">{actions}</div>}</div>;
}
function LoadingBlock({ label = 'Loading workspace data' }: { label?: string }) { return <div className="panel loading-panel" role="status"><div className="skeleton-line wide"/><div className="skeleton-line"/><span className="muted">{label}…</span></div>; }
function ErrorState({ onRetry }: { onRetry: () => void }) { return <div className="panel empty-state"><div className="empty-icon"><RefreshCw size={19}/></div><h3>Could not load this view</h3><p>The service may be unavailable. Your work has not been changed.</p><button className="action-btn" onClick={onRetry} data-testid="button-retry">Try again</button></div>; }
function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Layers3 size={19}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>; }
function MetricTile({ label, value, unit, icon: Icon }: { label: string; value: string; unit?: string; icon: typeof Activity }) { return <div className="panel metric-tile"><div className="metric-top"><span className="eyebrow">{label}</span><Icon size={15}/></div><div className="metric-value">{value}<small>{unit}</small></div></div>; }
function DataTable({ headers, children }: { headers: string[]; children: ReactNode }) { return <div className="table-scroll"><table><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function AiExplanation({ available, explanation, pending, isError, onGenerate, testId }: { available: boolean; explanation?: string; pending: boolean; isError: boolean; onGenerate: () => void; testId: string }) {
  return <div className="ai-explanation-controls">
    {available ? <>
      <button className="mini-action" onClick={onGenerate} disabled={pending} data-testid={testId}><Sparkles size={13}/>{pending ? 'Writing AI commentary…' : 'Explain with AI'}</button>
      {isError && <p className="error-text" role="alert">AI commentary could not be generated. The deterministic recommendation is unchanged.</p>}
      {explanation && <div className="ai-explanation" role="status" aria-live="polite"><div className="ai-explanation-label">AI COMMENTARY · OPTIONAL</div><p>{explanation}</p><small>This commentary explains simulated metrics; it does not choose or change the recommended policy.</small></div>}
    </> : <small className="ai-explanation-unavailable" data-testid={`${testId}-unavailable`}>AI commentary is disabled until Replit AI is configured.</small>}
  </div>;
}

function Dashboard() {
  const qc = useQueryClient();
  const q = useGetDashboard(); const alg = useListAlgorithms(); const health = useGetAgentHealth({ query: { queryKey: getGetAgentHealthQueryKey(), refetchInterval: 5000 } });
  const workloadsQ = useListWorkloads(); const recommend = useCreateRecommendation(); const explain = useCreateRecommendationExplanation(); const runRecommended = useRunSimulations();
  const apiHealth = useHealthCheck();
  const [recommendWorkload, setRecommendWorkload] = useState('');
  const [recommendObjective, setRecommendObjective] = useState<RecommendationObjective>('balanced');
  const [recommendedRunId, setRecommendedRunId] = useState<number | null>(null);
  const workloadId = Number(recommendWorkload || workloadsQ.data?.[0]?.id || 0);
  const selectedWorkload = workloadsQ.data?.find(w => w.id === workloadId);
  const clearRecommendation = () => { recommend.reset(); explain.reset(); runRecommended.reset(); setRecommendedRunId(null); };
  const evaluateBestScheduler = () => {
    if (!workloadId) return;
    explain.reset();
    runRecommended.reset();
    setRecommendedRunId(null);
    recommend.mutate({ data: { workloadId, objective: recommendObjective, quantum: 3 } }, {
      onSuccess: () => { explain.reset(); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); },
    });
  };
  const explainRecommendation = () => {
    if (!workloadId || !recommend.data) return;
    explain.mutate({ data: { workloadId, objective: recommendObjective, quantum: 3 } });
  };
  const runBestScheduler = () => {
    if (!workloadId || !recommend.data) return;
    runRecommended.mutate({ data: { workloadId, algorithmIds: [recommend.data.recommendedAlgorithmId], quantum: 3 } }, {
      onSuccess: items => {
        if (items[0]) setRecommendedRunId(items[0].id);
        qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() });
        qc.invalidateQueries({ queryKey: getGetAnalyticsQueryKey() });
      },
    });
  };
  const dashboard = q.data;
  if (q.isLoading) return <Shell><div className="content-wrap"><LoadingBlock/></div></Shell>;
  if (q.isError) return <Shell><div className="content-wrap"><ErrorState onRetry={() => q.refetch()}/></div></Shell>;
  return <Shell><div className="content-wrap">
    <PageHeading kicker="OPERATING SYSTEMS · LAB" title="Scheduling, made inspectable." subtitle="Build workloads, run controlled comparisons, and understand exactly what each result means." actions={<Link href="/simulator" className="action-btn primary-btn" data-testid="button-start-simulation"><Plus size={15}/> New experiment</Link>}/>
    <section className="obtain-section">
      <div className="obtain-heading"><div className="eyebrow">START HERE · WORKLOAD INPUT</div><h2>How would you like to obtain your workload?</h2><p>Choose a source. AdaptiveOS runs a simulation of scheduling behavior; it never changes your computer’s real OS scheduling.</p></div>
      <div className="obtain-grid">
        <Link href="/simulator?source=generate" className="obtain-card panel" data-testid="card-obtain-generate"><span className="obtain-icon"><Sparkles size={18}/></span><span className="obtain-copy"><strong>Generate a Workload</strong><small>Build reproducible synthetic processes with a profile and seed.</small></span><ArrowRight size={16}/></Link>
        <Link href="/simulator?source=agent" className="obtain-card panel" data-testid="card-obtain-monitor"><span className="obtain-icon agent"><MonitorDot size={18}/></span><span className="obtain-copy"><strong>Monitor My PC</strong><small>Use an explicitly opted-in local-agent snapshot as metadata, then estimate bursts.</small></span><ArrowRight size={16}/></Link>
      </div>
    </section>
    <section className="panel section-panel" data-testid="dashboard-auto-scheduler">
      <div className="section-title"><div><div className="eyebrow">AUTO-SELECT · FIVE BUILT-IN SCHEDULERS</div><h2>Find the best scheduler for your workload</h2><p className="small muted">AdaptiveOS simulates every built-in policy against the selected workload, recommends the best fit, and can run it for you.</p></div><div className="square-icon"><Sparkles size={17}/></div></div>
      {workloadsQ.isLoading ? <LoadingBlock label="Loading saved workloads"/> : workloadsQ.isError ? <ErrorState onRetry={() => workloadsQ.refetch()}/> : workloadsQ.data?.length ? <>
        <div className="form-grid">
          <label className="field-label">Saved workload<select className="field" value={String(workloadId)} onChange={e => { setRecommendWorkload(e.currentTarget.value); clearRecommendation(); }} data-testid="select-auto-workload">{workloadsQ.data.map(w => <option key={w.id} value={w.id}>{w.name} · {titleCase(w.profile)} · {w.processCount} processes</option>)}</select></label>
          <label className="field-label">Optimize for<select className="field" value={recommendObjective} onChange={e => { setRecommendObjective(e.currentTarget.value as RecommendationObjective); clearRecommendation(); }} data-testid="select-auto-objective"><option value="balanced">Balanced outcome</option><option value="waiting">Lowest average waiting</option><option value="turnaround">Lowest average turnaround</option><option value="response">Lowest average response</option></select></label>
        </div>
        <div className="manual-actions"><button className="action-btn primary-btn" onClick={evaluateBestScheduler} disabled={!workloadId||recommend.isPending} data-testid="button-auto-recommend">{recommend.isPending?'Comparing schedulers…':'Find best scheduler'}</button><span className="muted small">{selectedWorkload ? `${selectedWorkload.processCount} processes · ${titleCase(selectedWorkload.source)} input` : 'Choose a saved workload'}</span></div>
        {recommend.isError && <p className="error-text" role="alert" data-testid="auto-recommend-error">Could not evaluate this workload. Please retry.</p>}
        {recommend.data && <div className="recommendation-result" data-testid="auto-recommend-result">
          <div className="recommend-tag">BEST SIMULATED FIT · {titleCase(recommendObjective)}</div>
          <strong>{recommend.data.recommendedAlgorithmName}</strong>
          <p>{recommend.data.rationale}</p>
          <small>Compared all five built-in policies; the recommendation is a deterministic simulation result, not an AI prediction.</small>
          <AiExplanation available={recommend.data.aiExplanationAvailable} explanation={explain.data?.explanation} pending={explain.isPending} isError={explain.isError} onGenerate={explainRecommendation} testId="button-explain-auto-recommendation"/>
          <button className="action-btn full-btn" onClick={runBestScheduler} disabled={runRecommended.isPending} data-testid="button-run-recommended">{runRecommended.isPending?'Running recommended scheduler…':`Run ${recommend.data.recommendedAlgorithmName}`}</button>
        </div>}
        {runRecommended.isError && <p className="error-text" role="alert" data-testid="auto-run-error">The recommendation was found, but its simulation could not be saved. Please retry.</p>}
        {recommendedRunId && <div className="callout" role="status" data-testid="auto-run-success"><Check size={14}/><span>Recommended scheduler run saved.</span><Link href={`/simulator?workload=${workloadId}&run=${recommendedRunId}`} className="text-link">Inspect result <ArrowRight size={13}/></Link></div>}
      </> : <Empty title="Create a workload to get a recommendation" detail="The best fit is calculated from actual process arrivals, burst estimates, and the objective you choose." action={<Link href="/simulator?source=generate" className="text-link">Build a workload <ArrowRight size={14}/></Link>}/>}
    </section>
    <div className="stats-grid">
      <MetricTile label="SAVED WORKLOADS" value={String(dashboard?.workloadCount ?? 0)} unit="sets" icon={Layers3}/>
      <MetricTile label="SIMULATIONS RUN" value={String(dashboard?.simulationCount ?? 0)} unit="runs" icon={Activity}/>
      <MetricTile label="PROCESSES ANALYZED" value={String(dashboard?.processCount ?? 0)} unit="processes" icon={Cpu}/>
      <MetricTile label="RESULTS SHARED" value={String(dashboard?.sharedResultCount ?? 0)} unit="public" icon={Share2}/>
    </div>
    <div className="dashboard-grid">
      <section className="panel section-panel"><div className="section-title"><div><div className="eyebrow">RECENT ACTIVITY</div><h2>Latest simulations</h2></div><Link href="/analytics" className="text-link" data-testid="link-all-runs">All runs <ArrowRight size={14}/></Link></div>
        {dashboard?.recentSimulations?.length ? <DataTable headers={['Scheduler','Workload','Avg. wait · sim units','Turnaround · sim units','Created']}>{dashboard.recentSimulations.slice(0,6).map(s => <tr key={s.id} data-testid={`row-recent-simulation-${s.id}`}><td><strong>{s.algorithmName}</strong></td><td>{s.workloadName}</td><td className="mono">{pretty(s.metrics.averageWaitingTime)}</td><td className="mono">{pretty(s.metrics.averageTurnaroundTime)}</td><td className="muted">{dateLabel(s.createdAt)}</td></tr>)}</DataTable> : <Empty title="No runs yet" detail="Your comparison history will appear here once you run an experiment." action={<Link href="/simulator" className="text-link" data-testid="link-first-run">Create a first run <ArrowRight size={14}/></Link>}/>}
      </section>
      <section className="panel section-panel"><div className="section-title"><div><div className="eyebrow">SYSTEM CONTEXT</div><h2>Research tools</h2></div><div className="square-icon"><MonitorDot size={17}/></div></div>
        <div className="context-row"><div className="context-icon"><Radio size={16}/></div><div className="context-content"><strong>Local observation agent</strong><span>{health.data?.connected ? 'Connected · opt-in observations available' : 'Not connected · simulations work independently'}</span></div><span className={`status-pill ${health.data?.connected ? 'status-ok' : 'status-neutral'}`} data-testid="status-agent">{health.isLoading ? 'CHECKING' : health.data?.connected ? 'ONLINE' : 'OFFLINE'}</span></div>
        <div className="context-row"><div className="context-icon"><ListTree size={16}/></div><div className="context-content"><strong>Scheduler library</strong><span>{alg.data?.length ?? 0} built-in policies ready for comparison</span></div><span className="status-pill status-ok">{alg.isLoading ? '…' : 'READY'}</span></div>
        <div className="context-row"><div className="context-icon"><Activity size={16}/></div><div className="context-content"><strong>API service</strong><span>{apiHealth.data?.status === 'ok' ? 'Workbench services responding' : 'Service health is being checked'}</span></div><span className={`status-pill ${apiHealth.data?.status === 'ok' ? 'status-ok' : 'status-neutral'}`}>{apiHealth.isLoading ? 'CHECKING' : apiHealth.data?.status?.toUpperCase() || 'UNKNOWN'}</span></div>
        <div className="context-note"><CircleHelp size={14}/><span>Agent data is explicitly opt-in. Process names and OS observations are separate from estimated CPU bursts.</span></div>
      </section>
    </div>
    <section className="panel section-panel lower-panel"><div className="section-title"><div><div className="eyebrow">WORKLOAD LIBRARY</div><h2>Recent workload sets</h2></div><Link href="/simulator" className="text-link" data-testid="link-workload-library">Manage workloads <ArrowRight size={14}/></Link></div>
      {dashboard?.recentWorkloads?.length ? <div className="workload-list">{dashboard.recentWorkloads.slice(0,5).map(w => <div className="workload-row" key={w.id} data-testid={`row-workload-${w.id}`}><div className="workload-symbol"><Database size={16}/></div><div className="workload-main"><strong>{w.name}</strong><span>{titleCase(w.profile)} · {w.processCount} processes</span></div><span className="source-chip">{titleCase(w.source)}</span><span className="muted">{dateLabel(w.createdAt)}</span><Link href={`/simulator?workload=${w.id}`} className="icon-button" aria-label={`Open ${w.name}`} data-testid={`link-open-workload-${w.id}`}><ArrowRight size={15}/></Link></div>)}</div> : <Empty title="Your library is ready" detail="Generate a synthetic workload, enter processes manually, or import a CSV to begin." action={<Link href="/simulator" className="text-link" data-testid="link-create-workload">Build a workload <ArrowRight size={14}/></Link>}/>}
    </section>
  </div></Shell>;
}

function Simulator() {
  const qc = useQueryClient();
  const workloadsQ = useListWorkloads(); const algorithmsQ = useListAlgorithms(); const runsQ = useListSimulations();
  const health = useGetAgentHealth({ query: { queryKey: getGetAgentHealthQueryKey(), refetchInterval: 5000 } }); const snapshotsQ = useListAgentSnapshots({ query: { queryKey: getListAgentSnapshotsQueryKey(), refetchInterval: 5000 } });
  const createWorkload = useCreateWorkload(); const importCsv = useImportWorkloadCsv(); const deleteWorkload = useDeleteWorkload();
  const run = useRunSimulations(); const recommend = useCreateRecommendation(); const explain = useCreateRecommendationExplanation();
  const deleteSnapshot = useDeleteAgentSnapshot(); const createFromAgent = useCreateAgentWorkload();
  const [name, setName] = useState(''); const [profile, setProfile] = useState('mixed'); const [seed, setSeed] = useState('31415'); const [processCount, setProcessCount] = useState('6');
  const [arrivalWindow, setArrivalWindow] = useState('20'); const [priorityMin, setPriorityMin] = useState('1'); const [priorityMax, setPriorityMax] = useState('8'); const [memoryMin, setMemoryMin] = useState('64'); const [memoryMax, setMemoryMax] = useState('512');
  const [csvName, setCsvName] = useState('Imported workload'); const [csv, setCsv] = useState('pid,arrivalTime,burstTime,priority,memoryMb\nP1,0,8,2,128\nP2,1,4,1,64'); const [csvFileName,setCsvFileName]=useState(''); const [csvValidation,setCsvValidation]=useState<{valid:boolean;message:string;rows:number}>({valid:true,message:'Sample CSV ready. Review the preview, then import.',rows:2});
  const [manualProcesses,setManualProcesses]=useState([{pid:'P1',arrivalTime:0,burstTime:6,priority:1,memoryMb:128}]);
  const [quantum,setQuantum]=useState('3'); const [agentScopeBySnapshot,setAgentScopeBySnapshot]=useState<Record<number,boolean>>({});
  const [inspectedSnapshots,setInspectedSnapshots]=useState<number[]>([]);
  const [workloadId, setWorkloadId] = useState<number | null>(() => {
    const requestedId = Number(new URLSearchParams(window.location.search).get('workload'));
    return Number.isInteger(requestedId) && requestedId > 0 ? requestedId : null;
  }); const [algorithmIds, setAlgorithmIds] = useState<string[]>([]);
   const [selectedRun, setSelectedRun] = useState<number | null>(() => {
     const requestedRun = Number(new URLSearchParams(window.location.search).get('run'));
     return Number.isInteger(requestedRun) && requestedRun > 0 ? requestedRun : null;
   }); const [objective, setObjective] = useState('balanced'); const [recommendation, setRecommendation] = useState<any>(null);
  const clearRecommendation = () => { recommend.reset(); explain.reset(); setRecommendation(null); };
  const workloadQ = useGetWorkload(workloadId ?? 0, { query: { enabled: !!workloadId, queryKey: getGetWorkloadQueryKey(workloadId ?? 0) } });
  const simulationQ = useGetSimulation(selectedRun ?? 0, { query: { enabled: !!selectedRun, queryKey: getGetSimulationQueryKey(selectedRun ?? 0) } });
  const [tab, setTab] = useState<'generate'|'import'|'agent'|'manual'>(() => {
    const source = new URLSearchParams(window.location.search).get('source');
    return source === 'agent' ? 'agent' : source === 'manual' ? 'manual' : source === 'import' ? 'import' : 'generate';
  });
  const invalidateWorkloads = () => { qc.invalidateQueries({ queryKey: getListWorkloadsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getListSimulationsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAnalyticsQueryKey() }); };
  const generationRangesValid = Number.isFinite(Number(arrivalWindow)) && Number(arrivalWindow) >= 0
    && Number.isFinite(Number(priorityMin)) && Number(priorityMin) >= 1
    && Number.isFinite(Number(priorityMax)) && Number(priorityMax) >= Number(priorityMin)
    && Number.isFinite(Number(memoryMin)) && Number(memoryMin) >= 0
    && Number.isFinite(Number(memoryMax)) && Number(memoryMax) >= Number(memoryMin);
  const processInput = Array.from({ length: Math.max(1, Math.min(100, Number(processCount) || 1)) }, (_, i) => {
    const seedValue = Number(seed) || 0;
    const mixedSeed = (Math.imul(i + 1, 1103515245) + Math.imul(seedValue, 12345)) >>> 0;
    const random = mixedSeed / 4294967296;
    const window = Number(arrivalWindow) || 0;
    const arrivalProgress = i / Math.max(1, Number(processCount) - 1);
    const profileSpread = profile === 'short-job-heavy' ? .5 : profile === 'cpu-intensive' ? .72 : .88;
    const arrivalTime = i === 0 || window === 0 ? 0 : Math.max(0, Math.min(window, Math.floor(arrivalProgress * window * profileSpread + (random - .5) * Math.min(4, window))));
    const burstTime = profile === 'cpu-intensive' ? 12 + Math.floor(random * 28)
      : profile === 'short-job-heavy' ? 1 + Math.floor(random * 5)
      : profile === 'memory-heavy' ? 4 + Math.floor(random * 13)
      : profile === 'random' ? 1 + Math.floor(random * 40)
      : 3 + Math.floor(random * (i % 4 === 0 ? 24 : 12));
    const memoryDistribution = profile === 'memory-heavy' ? Math.sqrt(random) : random;
    const memoryMb = Math.round(Number(memoryMin) + memoryDistribution * (Number(memoryMax) - Number(memoryMin)));
    const priority = Number(priorityMin) + Math.floor(random * (Number(priorityMax) - Number(priorityMin) + 1));
    return { pid: `P${String(i + 1).padStart(3,'0')}`, arrivalTime, burstTime, priority, memoryMb };
  });
  const onGenerate = (e: React.FormEvent) => { e.preventDefault(); createWorkload.mutate({ data: { name: name || `${titleCase(profile)} · ${new Date().toLocaleDateString()}`, description: 'Synthetic workload generated for controlled scheduler comparison.', source: 'generated', profile: profile as any, seed: Number(seed), processes: processInput } }, { onSuccess: w => { clearRecommendation(); setWorkloadId(w.id); setName(w.name); invalidateWorkloads(); } }); };
  const onImport = (e: React.FormEvent) => { e.preventDefault(); importCsv.mutate({ data: { name: csvName, csv } }, { onSuccess: w => { clearRecommendation(); setWorkloadId(w.id); invalidateWorkloads(); } }); };
  const validateCsv = (value:string) => {
    const lines=value.trim().split(/\r?\n/).filter(Boolean);
    const required=['pid','arrivaltime','bursttime','priority','memorymb'];
    const header=(lines[0]||'').split(',').map(v=>v.trim().toLowerCase());
    const headerOk=required.every(k=>header.includes(k));
    const dataLines=lines.slice(1);
    const rowsValid=dataLines.length>0&&dataLines.every(line=>{const cells=line.split(',');const at=header.indexOf('arrivaltime'),bt=header.indexOf('bursttime'),pr=header.indexOf('priority'),mm=header.indexOf('memorymb');return cells.length>=header.length&&Number(cells[at])>=0&&Number(cells[bt])>0&&Number.isFinite(Number(cells[pr]))&&Number(cells[mm])>=0;});
    const valid=headerOk&&rowsValid;
    setCsvValidation({valid,rows:dataLines.length,message:!headerOk?'Required columns: pid, arrivalTime, burstTime, priority, memoryMb.':!dataLines.length?'Add at least one process row.':!rowsValid?'One or more rows has invalid numeric values or missing columns.':'CSV structure looks valid. The API will perform final validation.'});
  };
  const saveManual=()=>{createWorkload.mutate({data:{name:name.trim()||'Manual workload',description:'Process inputs entered manually.',source:'manual',profile:'mixed',seed:null,processes:manualProcesses}},{onSuccess:w=>{clearRecommendation();setWorkloadId(w.id);invalidateWorkloads();}});};
  const doRun = () => { if (!workloadId || !algorithmIds.length) return; run.mutate({ data: { workloadId, algorithmIds, quantum: Number(quantum) || 3 } }, { onSuccess: items => { qc.invalidateQueries({ queryKey: getListSimulationsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetAnalyticsQueryKey() }); if (items?.[0]) setSelectedRun(items[0].id); } }); };
  const doRecommend = () => { if (!workloadId) return; clearRecommendation(); recommend.mutate({ data: { workloadId, objective: objective as any, quantum: Number(quantum) || 3 } }, { onSuccess: setRecommendation }); };
  const explainRecommendation = () => {
    const activeRecommendation = recommendation || recommend.data;
    if (!workloadId || !activeRecommendation) return;
    explain.mutate({ data: { workloadId, objective: activeRecommendation.objective as RecommendationObjective, quantum: Number(quantum) || 3 } });
  };
  const toggleAlgorithm = (id: string) => setAlgorithmIds(prev => prev.includes(id) ? prev.filter(v => v !== id) : prev.length < 5 ? [...prev, id] : prev);
  if (workloadsQ.isLoading || algorithmsQ.isLoading || runsQ.isLoading) return <Shell><div className="content-wrap"><LoadingBlock label="Loading simulation workbench"/></div></Shell>;
  return <Shell><div className="content-wrap">
    <PageHeading kicker="EXPERIMENT DESIGN" title="Simulation workbench" subtitle="Create a reproducible workload, choose scheduling policies, and compare modeled outcomes." actions={<span className="status-pill status-neutral"><span className="status-dot"/> NO OS CHANGES</span>}/>
    <div className="sim-layout">
      <div className="sim-primary">
        <section className="panel builder-panel">
          <div className="panel-heading"><div><div className="eyebrow">01 / INPUT DATA</div><h2>Choose a workload</h2></div><span className="step-number">01</span></div>
          <div className="tabs" role="tablist">{[['generate','Generate'],['manual','Manual'],['import','Import CSV'],['agent','Monitor PC']].map(([key,label]) => <button key={key} onClick={() => {setTab(key as any);if(key==='import')validateCsv(csv);}} className={`tab ${tab === key ? 'selected' : ''}`} role="tab" aria-selected={tab === key} data-testid={`tab-${key}`}>{label}</button>)}</div>
          {tab === 'generate' && <form onSubmit={onGenerate} className="form-stack">
            <label className="field-label">Workload name<input className="field" placeholder="e.g. Mixed arrivals — week 4" value={name} onChange={e => setName(e.target.value)} data-testid="input-workload-name"/></label>
            <div className="field-grid"><label className="field-label">Workload profile<select className="field" value={profile} onChange={e => setProfile(e.target.value)} data-testid="select-profile">{['mixed','cpu-intensive','short-job-heavy','memory-heavy','random'].map(p => <option key={p} value={p}>{titleCase(p)}</option>)}</select></label><label className="field-label">Deterministic seed<input className="field mono" type="number" step="1" required value={seed} onChange={e => setSeed(e.target.value)} data-testid="input-seed"/></label></div>
            <label className="field-label">Process count <div className="range-row"><input type="range" min="2" max="100" value={processCount} onChange={e => setProcessCount(e.target.value)} data-testid="input-process-count"/><input className="field count-number" type="number" min="1" max="100" value={processCount} onChange={e => setProcessCount(String(Math.max(1,Math.min(100,Number(e.target.value)||1))))} data-testid="input-process-count-number"/><span className="count-chip mono">{processCount} jobs</span></div></label>
            <div className="field-grid generator-ranges"><label className="field-label">Arrival window · time units<input className="field" type="number" min="0" max="10000" step="1" required value={arrivalWindow} onChange={e=>setArrivalWindow(e.target.value)} data-testid="input-arrival-window"/></label><label className="field-label">Minimum priority<input className="field" type="number" min="1" max="100" step="1" required value={priorityMin} onChange={e=>setPriorityMin(e.target.value)} data-testid="input-priority-min"/></label><label className="field-label">Maximum priority<input className="field" type="number" min="1" max="100" step="1" required value={priorityMax} onChange={e=>setPriorityMax(e.target.value)} data-testid="input-priority-max"/></label><label className="field-label">Minimum memory · MB<input className="field" type="number" min="0" max="100000" step="1" required value={memoryMin} onChange={e=>setMemoryMin(e.target.value)} data-testid="input-memory-min"/></label><label className="field-label">Maximum memory · MB<input className="field" type="number" min="0" max="100000" step="1" required value={memoryMax} onChange={e=>setMemoryMax(e.target.value)} data-testid="input-memory-max"/></label></div>
            {!generationRangesValid && <div className="inline-error" role="alert">Maximum priority and memory must be at least their minimums. Ranges must be valid numbers.</div>}
            <div className="generation-preview"><span className="eyebrow">PROFILE PREVIEW</span><span>{titleCase(profile)} · burst range {profile==='cpu-intensive'?'12–39':profile==='short-job-heavy'?'1–5':profile==='memory-heavy'?'4–16':profile==='random'?'1–40':'3–26'} time units · arrivals 0–{arrivalWindow} · priorities {priorityMin}–{priorityMax} · memory {memoryMin}–{memoryMax} MB · seed {seed || 0}</span></div>
            <div className="callout"><CircleHelp size={14}/><span>Profile and seed deterministically shape arrivals, bursts, priorities, and memory. These are simulated inputs—not observations from a real machine.</span></div>
            <button className="action-btn primary-btn full-btn" disabled={createWorkload.isPending || !generationRangesValid} data-testid="button-generate-workload"><Sparkles size={15}/>{createWorkload.isPending ? 'Generating…' : 'Generate workload'}</button>
          </form>}
          {tab === 'manual' && <div className="form-stack">
            <label className="field-label">Workload name<input className="field" placeholder="Manual process set" value={name} onChange={e=>setName(e.target.value)} data-testid="input-manual-workload-name"/></label>
            <div className="callout"><CircleHelp size={14}/><span>Enter arrival and burst as simulation time units. Manually supplied values are not live operating-system measurements.</span></div>
            <div className="manual-process-editor"><div className="manual-grid manual-grid-head"><span>PID</span><span>ARRIVAL</span><span>BURST</span><span>PRIORITY</span><span>MEMORY MB</span><span/></div>{manualProcesses.map((p,i)=><div className="manual-grid" key={i}><input className="field" aria-label={`PID row ${i+1}`} value={p.pid} onChange={e=>setManualProcesses(v=>v.map((x,j)=>j===i?{...x,pid:e.target.value}:x))} data-testid={`input-manual-pid-${i}`}/><input className="field" aria-label={`Arrival time row ${i+1}`} type="number" min="0" value={p.arrivalTime} onChange={e=>setManualProcesses(v=>v.map((x,j)=>j===i?{...x,arrivalTime:Number(e.target.value)}:x))} data-testid={`input-manual-arrival-${i}`}/><input className="field" aria-label={`Burst time row ${i+1}`} type="number" min=".1" step=".1" value={p.burstTime} onChange={e=>setManualProcesses(v=>v.map((x,j)=>j===i?{...x,burstTime:Number(e.target.value)}:x))} data-testid={`input-manual-burst-${i}`}/><input className="field" aria-label={`Priority row ${i+1}`} type="number" value={p.priority} onChange={e=>setManualProcesses(v=>v.map((x,j)=>j===i?{...x,priority:Number(e.target.value)}:x))} data-testid={`input-manual-priority-${i}`}/><input className="field" aria-label={`Memory megabytes row ${i+1}`} type="number" min="0" value={p.memoryMb} onChange={e=>setManualProcesses(v=>v.map((x,j)=>j===i?{...x,memoryMb:Number(e.target.value)}:x))} data-testid={`input-manual-memory-${i}`}/><button className="icon-button" aria-label={`Remove process row ${i+1}`} disabled={manualProcesses.length<=1} onClick={()=>setManualProcesses(v=>v.filter((_,j)=>j!==i))} data-testid={`button-remove-process-${i}`}><Trash2 size={14}/></button></div>)}</div>
            <div className="manual-actions"><button className="action-btn" disabled={manualProcesses.length>=500} onClick={()=>setManualProcesses(v=>[...v,{pid:`P${v.length+1}`,arrivalTime:0,burstTime:1,priority:1,memoryMb:64}])} data-testid="button-add-process"><Plus size={14}/> Add process</button><button className="action-btn primary-btn" disabled={createWorkload.isPending||manualProcesses.some(p=>!p.pid.trim()||p.arrivalTime<0||p.burstTime<=0||p.memoryMb<0)} onClick={saveManual} data-testid="button-save-manual-workload">{createWorkload.isPending?'Saving…':'Save manual workload'}</button></div>
          </div>}
          {tab === 'import' && <form onSubmit={onImport} className="form-stack"><label className="field-label">Workload name<input className="field" value={csvName} onChange={e => setCsvName(e.target.value)} data-testid="input-import-name"/></label><label className="file-picker"><FileUp size={16}/><span>{csvFileName || 'Select a .csv file'}</span><input type="file" accept=".csv,text/csv" onChange={e=>{const file=e.currentTarget.files?.[0];if(file){setCsvFileName(file.name);void file.text().then(text=>{setCsv(text);validateCsv(text);});}}} data-testid="input-csv-file"/></label><label className="field-label">CSV process data<textarea className="field code-area" rows={6} value={csv} onChange={e => {setCsv(e.target.value);validateCsv(e.target.value);}} data-testid="input-csv"/></label><div className={`csv-validation ${csvValidation.valid?'valid':''}`} role="status"><span className="status-dot"/><span>{csvValidation.message}</span>{csvValidation.rows>0&&<strong>{csvValidation.rows} rows</strong>}</div><div className="csv-preview"><div className="eyebrow">DATA PREVIEW · FIRST 5 ROWS</div><pre>{csv.trim().split(/\r?\n/).slice(0,6).join('\n')}</pre></div><div className="callout"><FileUp size={14}/><span>Required columns: pid, arrivalTime, burstTime, priority, memoryMb. The API performs final validation on import.</span></div><button className="action-btn primary-btn full-btn" disabled={importCsv.isPending||!csvValidation.valid} data-testid="button-import-csv"><Upload size={15}/>{importCsv.isPending ? 'Validating…' : 'Validate & import CSV'}</button></form>}
          {tab === 'agent' && <div className="form-stack"><div className="agent-status-box"><span className={`agent-orb ${health.data?.connected ? 'is-online' : ''}`}><Radio size={20}/></span><div><strong>Local observation agent</strong><p>{health.data?.connected ? `Connected${health.data.lastSeenAt ? ` · last seen ${dateLabel(health.data.lastSeenAt)}` : ''}` : 'No agent connected. You can still use all synthetic and imported workloads.'}</p></div><span className={`status-pill ${health.data?.connected ? 'status-ok' : 'status-neutral'}`}>{health.data?.connected ? 'ONLINE' : 'OFFLINE'}</span></div>
            <div className="agent-instructions"><div className="eyebrow">CONNECT YOUR LOCAL AGENT</div><p>From the project folder on the PC you want to observe, install the optional dependency once:</p><pre>py -m pip install -r requirements.txt</pre><p>Start repeat sampling. Press Ctrl+C in that terminal to stop:</p><pre>python agent.py --server-url http://127.0.0.1:5000 --interval 2 --repeat</pre><p>For this local address, run the API on port 5000 and open the matching local workbench. For a hosted workbench, use that server's API origin instead and configure the same <code>AGENT_ACCESS_TOKEN</code> on the API and agent. Never paste the token into the browser.</p><p>The browser does not scan your PC. The agent uploads opt-in process metadata; this page refreshes health and snapshots automatically.</p></div>
            <div className="callout warning-callout"><CircleHelp size={14}/><span>Agent observations can include process IDs, names, status, CPU and memory. Capture is opt-in; the agent does not control scheduling. CPU bursts are estimates.</span></div>
            {!health.data?.connected && <p className="micro-hint">Start the companion agent using the instructions above. New snapshots will appear here automatically.</p>}
            <div className="snapshot-list">{snapshotsQ.data?.map(s => <div className="snapshot-row snapshot-card" key={s.id}><div className="snapshot-row-head"><div><strong>Snapshot {s.id}</strong><span>{s.processCount} observed processes · {dateLabel(s.observedAt)}</span></div><button className="icon-button" aria-label={`Delete snapshot ${s.id}`} onClick={() => deleteSnapshot.mutate({ snapshotId: s.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAgentSnapshotsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAgentHealthQueryKey() }); } })} data-testid={`button-delete-snapshot-${s.id}`}><Trash2 size={14}/></button></div><details className="snapshot-detail" onToggle={e=>{if(e.currentTarget.open)setInspectedSnapshots(v=>v.includes(s.id)?v:[...v,s.id]);}}><summary>Inspect observed process metadata</summary><DataTable headers={['PID','NAME','STATUS','CPU OBSERVED','MEMORY OBSERVED']}>{s.processes.map((p,i)=><tr key={`${p.pid}-${i}`}><td className="mono">{p.pid}</td><td>{p.name}</td><td>{p.status||'—'}</td><td>{p.cpuPercent ?? '—'}%</td><td>{p.memoryMb ?? '—'} MB</td></tr>)}</DataTable></details><div className="selection-inline"><label><input type="radio" name={`agent-process-scope-${s.id}`} checked={!(agentScopeBySnapshot[s.id]??false)} onChange={()=>setAgentScopeBySnapshot(v=>({...v,[s.id]:false}))} data-testid={`radio-active-processes-${s.id}`}/> Active-only</label><label><input type="radio" name={`agent-process-scope-${s.id}`} checked={agentScopeBySnapshot[s.id]??false} onChange={()=>setAgentScopeBySnapshot(v=>({...v,[s.id]:true}))} data-testid={`radio-all-processes-${s.id}`}/> All observed processes</label></div><button className="mini-action" disabled={!inspectedSnapshots.includes(s.id)||createFromAgent.isPending} onClick={() => createFromAgent.mutate({ data: { snapshotId: s.id, name: `Estimated workload · snapshot ${s.id}`, includeAll: agentScopeBySnapshot[s.id]??false } }, { onSuccess: w => { setWorkloadId(w.id); invalidateWorkloads(); } })} data-testid={`button-create-estimate-${s.id}`}>{inspectedSnapshots.includes(s.id)?'Create estimated workload':'Inspect before estimating'}</button></div>)}</div>
          </div>}
          {(createWorkload.isError || importCsv.isError || run.isError) && <div className="inline-error" role="alert">The request could not be completed. Review the input and try again.</div>}
        </section>
        <section className="panel builder-panel">
          <div className="panel-heading"><div><div className="eyebrow">02 / SCHEDULER SET</div><h2>Pick up to five policies</h2></div><span className="selection-count">{algorithmIds.length} selected</span></div>
          <div className="algorithm-picker">{algorithmsQ.data?.map((a,i) => <button key={a.id} className={`algorithm-option ${algorithmIds.includes(a.id) ? 'chosen' : ''}`} onClick={() => toggleAlgorithm(a.id)} data-testid={`button-algorithm-${a.id}`}><span className={`check-square ${algorithmIds.includes(a.id) ? 'checked' : ''}`}>{algorithmIds.includes(a.id) && <Check size={12}/>}</span><span className="algorithm-option-main"><strong>{a.name}</strong><small>{a.description}</small></span><span className="algorithm-flags">{a.preemptive ? 'PREEMPTIVE' : 'NON-PREEMPTIVE'}{a.configurable && ' · CONFIGURABLE'}</span></button>)}</div>
          <div className="run-controls"><div className="quantum-control"><label htmlFor="quantum">Round Robin quantum · time units</label><input id="quantum" className="field mono" type="number" min=".1" step=".1" value={quantum} onChange={e=>{setQuantum(e.target.value);clearRecommendation();}} data-testid="input-quantum"/></div><button className="action-btn primary-btn run-button" onClick={doRun} disabled={!workloadId || !algorithmIds.length || run.isPending} data-testid="button-run-comparison"><Play size={15} fill="currentColor"/>{run.isPending ? 'Running models…' : 'Run comparison'}</button></div>
          {!workloadId && <p className="micro-hint">Create or import a workload above to enable comparison.</p>}
        </section>
        {workloadQ.data && <section className="panel section-panel"><div className="section-title"><div><div className="eyebrow">SELECTED INPUT · {workloadQ.data.source.toUpperCase()}</div><h2>{workloadQ.data.name}</h2></div><span className="status-pill status-neutral">{workloadQ.data.processes.length} PROCESSES</span></div>
          {workloadQ.data.snapshotId && <div className="callout warning-callout"><CircleHelp size={14}/><span>Observed metadata is from an opt-in snapshot. Burst times below are estimated for simulation; outcomes are modeled.</span></div>}
          <DataTable headers={['PID','Arrival · sim units','Burst · sim units','Priority','Memory']}>{workloadQ.data.processes.map(p => <tr key={p.id}><td className="mono">{p.pid}</td><td>{p.arrivalTime}</td><td>{p.burstTime}{workloadQ.data?.snapshotId ? ' · estimated' : ''}</td><td>{p.priority}</td><td>{p.memoryMb} MB</td></tr>)}</DataTable>
        </section>}
      </div>
      <aside className="sim-aside">
        <section className="panel aside-card"><div className="eyebrow">WORKLOAD LIBRARY</div><h3>Saved inputs</h3><div className="saved-workloads">{workloadsQ.data?.length ? workloadsQ.data.map(w => <div key={w.id} className={`saved-workload ${workloadId === w.id ? 'is-selected' : ''}`}><button onClick={() => { setWorkloadId(w.id); clearRecommendation(); }} className="saved-select" data-testid={`button-select-workload-${w.id}`}><span className="saved-workload-icon"><Layers3 size={15}/></span><span><strong>{w.name}</strong><small>{titleCase(w.profile)} · {w.processCount} processes</small></span></button><button className="icon-button" aria-label={`Delete ${w.name}`} onClick={() => { if(confirm(`Delete "${w.name}" and its local simulation records?`)) deleteWorkload.mutate({ workloadId: w.id }, { onSuccess: () => { invalidateWorkloads(); if(workloadId === w.id) { setWorkloadId(null); clearRecommendation(); } } }); }} data-testid={`button-delete-workload-${w.id}`}><Trash2 size={14}/></button></div>) : <p className="muted small">New workload sets will appear here.</p>}</div></section>
        <section className="panel aside-card"><div className="eyebrow">TRANSPARENT GUIDANCE</div><h3>Recommendation</h3><p className="small muted">Evaluate policies against this exact input set. The selected policy is determined by simulation metrics; commentary is optional and cannot change it.</p><label className="field-label">Objective<select className="field" value={objective} onChange={e => { setObjective(e.target.value); clearRecommendation(); }} data-testid="select-objective"><option value="balanced">Balanced outcome</option><option value="waiting">Minimize waiting</option><option value="turnaround">Minimize turnaround</option><option value="response">Minimize response</option></select></label><div className="quantum-control recommendation-quantum"><label htmlFor="recommend-quantum">Round Robin quantum · time units</label><input id="recommend-quantum" className="field mono" type="number" min=".1" step=".1" value={quantum} onChange={e=>{setQuantum(e.target.value);clearRecommendation();}} data-testid="input-recommend-quantum"/></div><button className="action-btn full-btn" onClick={doRecommend} disabled={!workloadId || recommend.isPending} data-testid="button-recommend"><Sparkles size={14}/>{recommend.isPending ? 'Evaluating…' : 'Evaluate recommendation'}</button>
          {(recommendation || recommend.data) && <div className="recommendation-result"><div className="recommend-tag">DETERMINISTIC BEST FIT</div><strong>{(recommendation || recommend.data).recommendedAlgorithmName}</strong><p>{(recommendation || recommend.data).rationale}</p><small>{(recommendation || recommend.data).historicalEvidenceAvailable ? 'Historical evidence included' : 'Based on this workload evaluation only'}</small><AiExplanation available={(recommendation || recommend.data).aiExplanationAvailable} explanation={explain.data?.explanation} pending={explain.isPending} isError={explain.isError} onGenerate={explainRecommendation} testId="button-explain-simulator-recommendation"/></div>}
        </section>
        <section className="panel aside-card"><div className="eyebrow">LATEST RUNS</div><h3>Recent comparisons</h3>{runsQ.data?.length ? runsQ.data.slice(0,6).map(r => <button key={r.id} className={`run-history-row ${selectedRun === r.id ? 'selected' : ''}`} onClick={() => setSelectedRun(r.id)} data-testid={`button-open-run-${r.id}`}><span><strong>{r.algorithmName}</strong><small>{r.workloadName}</small></span><span className="mono">{pretty(r.metrics.averageWaitingTime)}<small>simulation-time wait</small></span></button>) : <p className="muted small">Run results will appear here.</p>}</section>
      </aside>
    </div>
    {simulationQ.data && <section className="panel section-panel results-panel"><div className="section-title"><div><div className="eyebrow">SIMULATION DETAIL · RUN {simulationQ.data.id}</div><h2>{simulationQ.data.algorithmName} <span className="muted">/ {simulationQ.data.workloadName}</span></h2></div><span className="status-pill status-neutral">MODELED RESULT</span></div>
      <div className="result-metrics"><MetricTile label="AVERAGE WAIT · SIM UNITS" value={pretty(simulationQ.data.metrics.averageWaitingTime)} unit="time" icon={Clock3}/><MetricTile label="TURNAROUND · SIM UNITS" value={pretty(simulationQ.data.metrics.averageTurnaroundTime)} unit="time" icon={Activity}/><MetricTile label="RESPONSE · SIM UNITS" value={pretty(simulationQ.data.metrics.averageResponseTime)} unit="time" icon={Gauge}/><MetricTile label="CPU UTILIZATION" value={pretty(simulationQ.data.metrics.cpuUtilization)} unit="%" icon={Cpu}/></div>
      <div className="gantt-wrap"><div className="eyebrow">GANTT TIMELINE · SIMULATED TIME UNITS</div><div className="gantt">{simulationQ.data.timeline.map((s,i) => {const width = Math.max(44, ((s.end-s.start) / Math.max(1,simulationQ.data!.metrics.totalDuration))*100); return <div key={i} className={`gantt-segment ${s.kind === 'idle' ? 'idle-segment' : ''}`} style={{width:`${width}%`}} title={`${s.pid}: ${s.start}–${s.end}`}><strong>{s.kind === 'idle' ? 'IDLE' : s.pid}</strong><small>{s.start}–{s.end}</small></div>;})}</div><div className="gantt-axis"><span>0</span><span>{simulationQ.data.metrics.totalDuration} time units</span></div></div>
      <div className="callout"><CircleHelp size={14}/><span>These outcomes are produced by the selected scheduling model using this workload's input values. They are not measurements of actual operating-system execution.</span></div>
    </section>}
  </div></Shell>;
}

function Analytics() {
  const qc = useQueryClient(); const analytics = useGetAnalytics(); const runs = useListSimulations(); const workloads = useListWorkloads(); const shared = useListSharedMetrics();
  const [workloadId, setWorkloadId] = useState<number | undefined>(); const analyticsFiltered = useGetAnalytics(workloadId ? { workloadId } : undefined, { query: { enabled: !!workloadId, queryKey: getGetAnalyticsQueryKey(workloadId ? { workloadId } : undefined) } });
  const [shareId, setShareId] = useState<number | null>(null); const [shareTitle, setShareTitle] = useState(''); const [author, setAuthor] = useState('OS student'); const share = useShareSimulation();
  const metricComments = useListMetricComments(shareId ?? 0, { query: { enabled: !!shareId, queryKey: getListMetricCommentsQueryKey(shareId ?? 0) } });
  const createComment = useCreateMetricComment(); const [comment, setComment] = useState('');
  const data = workloadId ? analyticsFiltered.data : analytics.data;
  const rows = data || [];
  const exportRows = () => { if (!rows.length) return; const cols = ['algorithmName','workloadName','averageWaitingTime','averageTurnaroundTime','averageResponseTime','cpuUtilization','throughput','totalDuration','createdAt']; const text = [cols.join(','), ...rows.map((r:any) => [r.algorithmName,r.workloadName,r.metrics.averageWaitingTime,r.metrics.averageTurnaroundTime,r.metrics.averageResponseTime,r.metrics.cpuUtilization,r.metrics.throughput,r.metrics.totalDuration,r.createdAt].join(','))].join('\n'); const blob = new Blob([text], {type:'text/csv'}); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'adaptiveos-analytics.csv'; a.click(); URL.revokeObjectURL(a.href); };
  const loadFailure = analytics.isError || runs.isError;
  return <Shell><div className="content-wrap">
    <PageHeading kicker="EVIDENCE & HISTORY" title="Analytics" subtitle="Review persisted simulation outcomes, compare policies, and export a reproducible record." actions={<button className="action-btn" onClick={exportRows} disabled={!rows.length} data-testid="button-export-csv"><ArrowDownToLine size={15}/> Export CSV</button>}/>
    <div className="filter-bar panel"><div className="filter-caption"><SlidersHorizontal size={15}/><span>FILTER HISTORY</span></div><label className="filter-control"><span>Workload</span><select className="field" value={workloadId ?? ''} onChange={e => setWorkloadId(e.target.value ? Number(e.target.value) : undefined)} data-testid="select-analytics-workload"><option value="">All workloads</option>{workloads.data?.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></label><button className="quiet-button" onClick={() => {setWorkloadId(undefined); qc.invalidateQueries({queryKey:getGetAnalyticsQueryKey()});}} data-testid="button-clear-filter">Clear filters</button><span className="filter-count">{rows.length} records</span></div>
    {loadFailure ? <ErrorState onRetry={() => {analytics.refetch(); runs.refetch();}}/> : analytics.isLoading ? <LoadingBlock label="Loading historical comparisons"/> : <div className="panel section-panel">
      <div className="section-title"><div><div className="eyebrow">PERSISTED SIMULATIONS</div><h2>Comparison history</h2></div><span className="status-pill status-neutral">MODEL OUTPUTS</span></div>
       {rows.length ? <DataTable headers={['Algorithm','Workload','Avg wait · sim units','Turnaround · sim units','Response · sim units','CPU util.','Throughput','Run time']} >{rows.map((r:any) => <tr key={r.id} data-testid={`row-analytics-${r.id}`}><td><strong>{r.algorithmName}</strong><small className="cell-sub">ID {r.id}</small></td><td>{r.workloadName}</td><td className="mono">{pretty(r.metrics.averageWaitingTime)}</td><td className="mono">{pretty(r.metrics.averageTurnaroundTime)}</td><td className="mono">{pretty(r.metrics.averageResponseTime)}</td><td className="mono">{pretty(r.metrics.cpuUtilization)}%</td><td className="mono">{pretty(r.metrics.throughput)}</td><td className="muted">{dateLabel(r.createdAt)}</td></tr>)}</DataTable> : <Empty title="No simulation evidence yet" detail="Run scheduler comparisons in the simulator. Analytics only reflects persisted model runs." action={<Link href="/simulator" className="text-link" data-testid="link-analytics-simulator">Open simulator <ArrowRight size={14}/></Link>}/>}
    </div>}
    <section className="panel section-panel"><div className="section-title"><div><div className="eyebrow">OPTIONAL PUBLIC RESULTS</div><h2>Shared metrics</h2></div><span className="muted small">Sharing requires an explicit action</span></div>
      {runs.data?.length ? <div className="share-launcher"><label className="field-label">Simulation<select className="field" value={shareId ?? ''} onChange={e => setShareId(e.target.value ? Number(e.target.value) : null)} data-testid="select-share-run"><option value="">Choose a persisted run…</option>{runs.data.map(r => <option value={r.id} key={r.id}>{r.algorithmName} · {r.workloadName} · #{r.id}</option>)}</select></label><label className="field-label">Result title<input className="field" value={shareTitle} onChange={e => setShareTitle(e.target.value)} placeholder="A useful, specific title" data-testid="input-share-title"/></label><label className="field-label">Author<input className="field" value={author} onChange={e => setAuthor(e.target.value)} data-testid="input-share-author"/></label><button className="action-btn primary-btn" onClick={() => {if(shareId && shareTitle.trim()) share.mutate({simulationId:shareId,data:{title:shareTitle.trim(),authorName:author.trim() || 'OS student'}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListSharedMetricsQueryKey()});setShareTitle('');}});}} disabled={!shareId || !shareTitle.trim() || share.isPending} data-testid="button-share-run"><Share2 size={14}/>{share.isPending ? 'Sharing…' : 'Share result'}</button></div> : <p className="muted small">Run a simulation before sharing a result.</p>}
      {shared.data?.length ? <div className="shared-list">{shared.data.map(m => <article className="shared-row" key={m.id} data-testid={`shared-metric-${m.id}`}><div className="shared-title"><strong>{m.title}</strong><span>{m.authorName} · {m.algorithmName} · {m.workloadName} · {m.processCount} processes</span></div><div className="shared-metric-values"><span><small>WAIT</small>{pretty(m.metrics.averageWaitingTime)}</span><span><small>TURNAROUND</small>{pretty(m.metrics.averageTurnaroundTime)}</span></div><button className="mini-action" onClick={() => setShareId(m.id)} data-testid={`button-open-comments-${m.id}`}><MessageSquare size={13}/>{m.commentCount} comments</button></article>)}</div> : <Empty title="Nothing shared publicly" detail="Sharing adds a result to the Community feed. This build has no sign-in or per-user data isolation; anyone who can access this workbench may query saved workloads, runs, and snapshots through its API."/>}
      {shareId && <div className="comment-box"><div className="section-title"><h3>Discussion on selected result</h3><button className="icon-button" onClick={() => setShareId(null)} aria-label="Close comments" data-testid="button-close-comments"><X size={15}/></button></div>{metricComments.data?.map(c => <div className="comment-row" key={c.id}><strong>{c.authorName}</strong><span>{c.message}</span></div>)}<form className="comment-entry" onSubmit={e => {e.preventDefault();if(comment.trim())createComment.mutate({metricId:shareId,data:{authorName:author,message:comment.trim()}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListMetricCommentsQueryKey(shareId)});qc.invalidateQueries({queryKey:getListSharedMetricsQueryKey()});setComment('');}});}}><input className="field" value={comment} onChange={e => setComment(e.target.value)} placeholder="Add a thoughtful comment…" data-testid="input-metric-comment"/><button className="action-btn" disabled={!comment.trim()} data-testid="button-submit-metric-comment">Post</button></form></div>}
    </section>
  </div></Shell>;
}

function Community() {
  const qc = useQueryClient(); const metrics = useListSharedMetrics(); const algorithms = useListCommunityAlgorithms(); const builtinAlgorithms = useListAlgorithms(); const discussions = useListDiscussions();
  const createAlgo = useCreateCommunityAlgorithm(); const createDiscussion = useCreateDiscussion();
  const [section, setSection] = useState<'metrics'|'algorithms'|'discussions'>('metrics');
  const [metricId,setMetricId]=useState<number|null>(null); const [algoId,setAlgoId]=useState<number|null>(null); const [discussionId,setDiscussionId]=useState<number|null>(null);
  const [inspectSimulationId,setInspectSimulationId]=useState<number|null>(null);
  const simulationDetail=useGetSimulation(inspectSimulationId??0,{query:{enabled:!!inspectSimulationId,queryKey:getGetSimulationQueryKey(inspectSimulationId??0)}});
  const metricComments=useListMetricComments(metricId??0,{query:{enabled:!!metricId,queryKey:getListMetricCommentsQueryKey(metricId??0)}});
  const algoComments=useListAlgorithmComments(algoId??0,{query:{enabled:!!algoId,queryKey:getListAlgorithmCommentsQueryKey(algoId??0)}});
  const discussionComments=useListDiscussionComments(discussionId??0,{query:{enabled:!!discussionId,queryKey:getListDiscussionCommentsQueryKey(discussionId??0)}});
  const addMetricComment=useCreateMetricComment(); const addAlgoComment=useCreateAlgorithmComment(); const addDiscussionComment=useCreateDiscussionComment();
  const [author,setAuthor]=useState('OS student'); const [message,setMessage]=useState('');
  const [showAlgorithmForm,setShowAlgorithmForm]=useState(false); const [algoName,setAlgoName]=useState(''); const [algoDescription,setAlgoDescription]=useState(''); const [sourceCode,setSourceCode]=useState(''); const [tags,setTags]=useState('scheduler, research');
  const [algorithmSourceView,setAlgorithmSourceView]=useState<{name:string,source:string}|null>(null); const [sourceFileName,setSourceFileName]=useState(''); const [algorithmSearch,setAlgorithmSearch]=useState('');
  const [showDiscussionForm,setShowDiscussionForm]=useState(false); const [discussionTitle,setDiscussionTitle]=useState(''); const [discussionBody,setDiscussionBody]=useState(''); const [category,setCategory]=useState('CPU Scheduling');
  const [metricAlgorithmFilter,setMetricAlgorithmFilter]=useState(''); const [metricWorkloadFilter,setMetricWorkloadFilter]=useState(''); const [metricSort,setMetricSort]=useState('newest');
  const [discussionSearch,setDiscussionSearch]=useState(''); const [discussionCategoryFilter,setDiscussionCategoryFilter]=useState('');
  const visibleMetrics=[...(metrics.data||[])].filter(m=>(!metricAlgorithmFilter||m.algorithmName===metricAlgorithmFilter)&&(!metricWorkloadFilter||m.workloadName===metricWorkloadFilter)).sort((a,b)=>metricSort==='wait'?a.metrics.averageWaitingTime-b.metrics.averageWaitingTime:metricSort==='turnaround'?a.metrics.averageTurnaroundTime-b.metrics.averageTurnaroundTime:metricSort==='utilization'?b.metrics.cpuUtilization-a.metrics.cpuUtilization:new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime());
  const builtinCards=(builtinAlgorithms.data||[]).map(a=>({...a,id:String(a.id),status:'built-in',tags:[],authorName:'AdaptiveOS',commentCount:0,sourceCode:(a as typeof a & {sourceCode?:string}).sourceCode||''}));
  const combinedAlgorithms=[...builtinCards,...(algorithms.data||[])].filter(a=>!algorithmSearch||`${a.name} ${a.description}`.toLowerCase().includes(algorithmSearch.toLowerCase()));
  const visibleDiscussions=(discussions.data||[]).filter(d=>(!discussionCategoryFilter||d.category===discussionCategoryFilter)&&(!discussionSearch||`${d.title} ${d.body} ${d.authorName}`.toLowerCase().includes(discussionSearch.toLowerCase())));
  const downloadSource=(filename:string,source:string,extension:'js'|'py')=>{const blob=new Blob([source],{type:'text/plain'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${filename.replace(/\.[^.]+$/,'')}.${extension}`;link.click();URL.revokeObjectURL(url);};
  const activeComments = section==='metrics' ? metricComments.data : section==='algorithms' ? algoComments.data : discussionComments.data;
  const closeComments=()=>{setMetricId(null);setAlgoId(null);setDiscussionId(null);setMessage('');};
  const submitComment=(e:React.FormEvent)=>{e.preventDefault();if(!message.trim())return;const data={authorName:author.trim()||'OS student',message:message.trim()};const done=()=>{if(metricId){qc.invalidateQueries({queryKey:getListMetricCommentsQueryKey(metricId)});qc.invalidateQueries({queryKey:getListSharedMetricsQueryKey()});}if(algoId){qc.invalidateQueries({queryKey:getListAlgorithmCommentsQueryKey(algoId)});qc.invalidateQueries({queryKey:getListCommunityAlgorithmsQueryKey()});}if(discussionId){qc.invalidateQueries({queryKey:getListDiscussionCommentsQueryKey(discussionId)});qc.invalidateQueries({queryKey:getListDiscussionsQueryKey()});}setMessage('');};if(metricId)addMetricComment.mutate({metricId,data},{onSuccess:done});if(algoId)addAlgoComment.mutate({algorithmId:algoId,data},{onSuccess:done});if(discussionId)addDiscussionComment.mutate({discussionId,data},{onSuccess:done});};
  const tabs=[{id:'metrics',label:'Performance Metrics',count:metrics.data?.length??0},{id:'algorithms',label:'Algorithms',count:algorithms.data?.length??0},{id:'discussions',label:'Discussions',count:discussions.data?.length??0}];
  return <Shell><div className="content-wrap">
    <PageHeading kicker="PEER RESEARCH" title="Community" subtitle="Compare shared outcomes, review unexecuted algorithm proposals, and discuss the evidence."/>
    <div className="community-tabs" role="tablist">{tabs.map(t=><button key={t.id} onClick={()=>{setSection(t.id as any);closeComments();}} className={`community-tab ${section===t.id?'selected':''}`} role="tab" aria-selected={section===t.id} data-testid={`tab-community-${t.id}`}><span>{t.label}</span><small>{t.count}</small></button>)}</div>
     {section==='metrics'&&<section className="community-feed">
       <div className="metric-filter-bar panel"><label className="field-label">Algorithm<select className="field" value={metricAlgorithmFilter} onChange={e=>setMetricAlgorithmFilter(e.target.value)} data-testid="select-metric-algorithm"><option value="">All algorithms</option>{Array.from(new Set((metrics.data||[]).map(m=>m.algorithmName))).map(v=><option key={v}>{v}</option>)}</select></label><label className="field-label">Workload<select className="field" value={metricWorkloadFilter} onChange={e=>setMetricWorkloadFilter(e.target.value)} data-testid="select-metric-workload"><option value="">All workloads</option>{Array.from(new Set((metrics.data||[]).map(m=>m.workloadName))).map(v=><option key={v}>{v}</option>)}</select></label><label className="field-label">Order<select className="field" value={metricSort} onChange={e=>setMetricSort(e.target.value)} data-testid="select-metric-sort"><option value="newest">Most recent</option><option value="wait">Lowest avg wait</option><option value="turnaround">Lowest turnaround</option><option value="utilization">Highest utilization</option></select></label><span className="filter-count">{visibleMetrics.length} results</span></div>
       {metrics.isLoading?<LoadingBlock/>:metrics.isError?<ErrorState onRetry={()=>metrics.refetch()}/>:visibleMetrics.length?visibleMetrics.map(m=><article className="panel community-card" key={m.id} data-testid={`community-metric-${m.id}`}><div className="community-card-head"><div><div className="eyebrow">PERFORMANCE METRIC · {m.processCount} PROCESSES</div><h2>{m.title}</h2><span className="muted small">{m.authorName} · {m.algorithmName} on {m.workloadName}</span></div><div className="metric-card-actions"><button className="mini-action" onClick={()=>setInspectSimulationId(inspectSimulationId===m.simulationId?null:m.simulationId)} data-testid={`button-inspect-simulation-${m.id}`}><Eye size={14}/>Inspect saved run</button><button className="mini-action" onClick={()=>{setMetricId(m.id);setAlgoId(null);setDiscussionId(null);}} data-testid={`button-comment-metric-${m.id}`}><MessageSquare size={14}/>{m.commentCount} replies</button></div></div><div className="community-metrics"><span><small>AVG WAIT · SIM TIME</small><strong>{pretty(m.metrics.averageWaitingTime)}<i>units</i></strong></span><span><small>TURNAROUND · SIM TIME</small><strong>{pretty(m.metrics.averageTurnaroundTime)}<i>units</i></strong></span><span><small>RESPONSE · SIM TIME</small><strong>{pretty(m.metrics.averageResponseTime)}<i>units</i></strong></span><span><small>CPU UTILIZATION</small><strong>{pretty(m.metrics.cpuUtilization)}<i>%</i></strong></span><span><small>THROUGHPUT</small><strong>{pretty(m.metrics.throughput)}</strong></span></div><div className="card-foot"><span>Simulation outcome · modeled, not live OS measurement</span><span>{dateLabel(m.createdAt)}</span></div></article>):<Empty title="No shared metrics match" detail="Clear an algorithm or workload filter, or share a persisted simulation from Analytics."/>}
       {inspectSimulationId&&<section className="panel section-panel linked-run-detail"><div className="section-title"><div><div className="eyebrow">LINKED SAVED SIMULATION · #{inspectSimulationId}</div><h2>{simulationDetail.data?.algorithmName||'Simulation details'}</h2></div><button className="icon-button" onClick={()=>setInspectSimulationId(null)} aria-label="Close simulation details" data-testid="button-close-simulation-details"><X size={15}/></button></div>{simulationDetail.isLoading?<LoadingBlock label="Loading linked simulation"/>:simulationDetail.isError?<ErrorState onRetry={()=>simulationDetail.refetch()}/>:simulationDetail.data&&<><p className="muted small">{simulationDetail.data.workloadName} · saved {dateLabel(simulationDetail.data.createdAt)} · outcomes in simulation time units</p><div className="community-metrics"><span><small>AVG WAIT</small><strong>{pretty(simulationDetail.data.metrics.averageWaitingTime)}</strong></span><span><small>TURNAROUND</small><strong>{pretty(simulationDetail.data.metrics.averageTurnaroundTime)}</strong></span><span><small>RESPONSE</small><strong>{pretty(simulationDetail.data.metrics.averageResponseTime)}</strong></span><span><small>CPU UTILIZATION</small><strong>{pretty(simulationDetail.data.metrics.cpuUtilization)}%</strong></span></div><div className="gantt"><>{simulationDetail.data.timeline.map((s,i)=><div className={`gantt-segment ${s.kind==='idle'?'idle-segment':''}`} key={i}><strong>{s.kind==='idle'?'IDLE':s.pid}</strong><small>{s.start}–{s.end} time units</small></div>)}</></div><DataTable headers={['PID','Arrival · sim units','Burst · sim units','Waiting · sim units','Turnaround · sim units']}>{simulationDetail.data.processes.map((p,i)=><tr key={`${p.pid}-${i}`}><td className="mono">{p.pid}</td><td>{p.arrivalTime}</td><td>{p.burstTime}</td><td>{p.waitingTime}</td><td>{p.turnaroundTime}</td></tr>)}</DataTable></>}</section>}
     </section>}
    {section==='algorithms'&&<section className="community-feed"><div className="feed-toolbar"><div><div className="eyebrow">COMMUNITY SUBMISSIONS</div><p>Source is displayed for review only; submissions are never executed.</p></div><button className="action-btn primary-btn" onClick={()=>setShowAlgorithmForm(v=>!v)} data-testid="button-toggle-algorithm-form"><Plus size={14}/>{showAlgorithmForm?'Close':'Submit algorithm'}</button></div>
       {showAlgorithmForm&&<form className="panel compose-form" onSubmit={e=>{e.preventDefault();createAlgo.mutate({data:{name:algoName,description:algoDescription,authorName:author,sourceCode,tags:tags.split(',').map(t=>t.trim()).filter(Boolean)}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListCommunityAlgorithmsQueryKey()});setShowAlgorithmForm(false);setAlgoName('');setAlgoDescription('');setSourceCode('');setSourceFileName('');}});}}><div className="form-grid"><label className="field-label">Algorithm name<input className="field" required value={algoName} onChange={e=>setAlgoName(e.target.value)} data-testid="input-algorithm-name"/></label><label className="field-label">Tags<input className="field" value={tags} onChange={e=>setTags(e.target.value)} data-testid="input-algorithm-tags"/></label></div><label className="field-label">Description<textarea className="field" required rows={2} value={algoDescription} onChange={e=>setAlgoDescription(e.target.value)} data-testid="input-algorithm-description"/></label><label className="file-picker"><FileUp size={16}/><span>{sourceFileName||'Select a .py source file'}</span><input type="file" accept=".py,text/x-python" onChange={e=>{const file=e.currentTarget.files?.[0];if(file){setSourceFileName(file.name);void file.text().then(text=>setSourceCode(text));}}} data-testid="input-algorithm-py-file"/></label><label className="field-label">Source code <span className="muted">(unexecuted; loaded locally only)</span><textarea className="field code-area" required rows={6} value={sourceCode} onChange={e=>setSourceCode(e.target.value)} data-testid="input-algorithm-code"/></label><button className="action-btn primary-btn" disabled={createAlgo.isPending} data-testid="button-submit-algorithm">{createAlgo.isPending?'Submitting…':'Submit for review'}</button></form>}
       <label className="search-filter"><Search size={15}/><input className="field" value={algorithmSearch} onChange={e=>setAlgorithmSearch(e.target.value)} placeholder="Filter built-in and community algorithms…" data-testid="input-algorithm-search"/></label>
       {algorithms.isLoading||builtinAlgorithms.isLoading?<LoadingBlock/>:algorithms.isError||builtinAlgorithms.isError?<ErrorState onRetry={()=>{algorithms.refetch();builtinAlgorithms.refetch();}}/>:combinedAlgorithms.length?combinedAlgorithms.map(a=><article className="panel algorithm-card" key={`${a.status}-${a.id}`} data-testid={`community-algorithm-${a.id}`}><div className="algorithm-card-head"><div className="algorithm-symbol"><ListTree size={18}/></div><div className="algorithm-card-title"><div className="eyebrow">{a.status==='built-in'?'BUILT-IN REFERENCE':'COMMUNITY PROPOSAL · SOURCE UNEXECUTED'}</div><h2>{a.name}</h2><p>{a.description}</p></div>{a.status!=='built-in'&&<button className="mini-action" onClick={()=>{setAlgoId(Number(a.id));setMetricId(null);setDiscussionId(null);}} data-testid={`button-comment-algorithm-${a.id}`}><MessageSquare size={14}/>{a.commentCount}</button>}</div><div className="tag-row">{a.tags.map(t=><span key={t} className="tag-chip">{t}</span>)}<span className={`status-pill ${a.status==='built-in'?'status-ok':'status-review'}`}>{a.status==='built-in'?'BUILT IN':'UNEXECUTED'}</span></div><div className="algorithm-source-actions">{a.sourceCode?<><button className="mini-action" onClick={()=>setAlgorithmSourceView({name:a.name,source:a.sourceCode})} data-testid={`button-view-source-${a.id}`}><Eye size={13}/>View source</button><button className="mini-action" onClick={()=>downloadSource(a.name,a.sourceCode,a.status==='built-in'?'js':'py')} data-testid={`button-download-source-${a.id}`}><Download size={13}/>{a.status==='built-in'?'Download .js':'Download .py'}</button></>:<span className="muted small">{a.status==='built-in'?'Source code was not returned by the API.':'Source unavailable.'}</span>}</div><div className="card-foot"><span>{a.status==='built-in'?'Built-in scheduler':'Proposed by '+a.authorName}</span><span>{'createdAt' in a ? dateLabel(a.createdAt) : ''}</span></div></article>):<Empty title="No algorithms match" detail="Try another search term."/>}
       {algorithmSourceView&&<section className="panel source-viewer"><div className="section-title"><div><div className="eyebrow">SOURCE VIEW · NEVER EXECUTED</div><h2>{algorithmSourceView.name}</h2></div><button className="icon-button" aria-label="Close source viewer" onClick={()=>setAlgorithmSourceView(null)} data-testid="button-close-source"><X size={15}/></button></div><pre>{algorithmSourceView.source}</pre></section>}
     </section>}
    {section==='discussions'&&<section className="community-feed"><div className="feed-toolbar"><div><div className="eyebrow">RESEARCH CONVERSATIONS</div><p>Ask about methodology, workload design, or interpretation.</p></div><button className="action-btn primary-btn" onClick={()=>setShowDiscussionForm(v=>!v)} data-testid="button-toggle-discussion-form"><Plus size={14}/>{showDiscussionForm?'Close':'Start discussion'}</button></div>
      {showDiscussionForm&&<form className="panel compose-form" onSubmit={e=>{e.preventDefault();createDiscussion.mutate({data:{title:discussionTitle,body:discussionBody,category:category as any,authorName:author}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListDiscussionsQueryKey()});setShowDiscussionForm(false);setDiscussionTitle('');setDiscussionBody('');}});}}><label className="field-label">Discussion title<input className="field" required value={discussionTitle} onChange={e=>setDiscussionTitle(e.target.value)} data-testid="input-discussion-title"/></label><div className="form-grid"><label className="field-label">Category<select className="field" value={category} onChange={e=>setCategory(e.target.value)} data-testid="select-discussion-category">{['CPU Scheduling','Operating Systems','Algorithms','Performance Analysis','Datasets','Project Help','General Discussion'].map(c=><option key={c}>{c}</option>)}</select></label><label className="field-label">Author<input className="field" value={author} onChange={e=>setAuthor(e.target.value)} data-testid="input-community-author"/></label></div><label className="field-label">Context<textarea className="field" required rows={4} value={discussionBody} onChange={e=>setDiscussionBody(e.target.value)} data-testid="input-discussion-body"/></label><button className="action-btn primary-btn" disabled={createDiscussion.isPending} data-testid="button-submit-discussion">{createDiscussion.isPending?'Publishing…':'Publish discussion'}</button></form>}
      <div className="discussion-filters panel"><label className="search-filter"><Search size={15}/><input className="field" value={discussionSearch} onChange={e=>setDiscussionSearch(e.target.value)} placeholder="Search discussions, authors, and context…" data-testid="input-discussion-search"/></label><label className="field-label">Category<select className="field" value={discussionCategoryFilter} onChange={e=>setDiscussionCategoryFilter(e.target.value)} data-testid="select-discussion-filter"><option value="">All categories</option>{['CPU Scheduling','Operating Systems','Algorithms','Performance Analysis','Datasets','Project Help','General Discussion'].map(c=><option key={c}>{c}</option>)}</select></label></div>
      {discussions.isLoading?<LoadingBlock/>:discussions.isError?<ErrorState onRetry={()=>discussions.refetch()}/>:visibleDiscussions.length?visibleDiscussions.map(d=><article className="panel discussion-card" key={d.id} data-testid={`community-discussion-${d.id}`}><div className="discussion-top"><span className="category-label">{d.category}</span><span className="muted small">{dateLabel(d.createdAt)}</span></div><h2>{d.title}</h2><p>{d.body}</p><div className="discussion-foot"><span>Started by <strong>{d.authorName}</strong></span><button className="mini-action" onClick={()=>{setDiscussionId(d.id);setMetricId(null);setAlgoId(null);}} data-testid={`button-comment-discussion-${d.id}`}><MessageSquare size={14}/>{d.commentCount} replies</button></div></article>):<Empty title="No discussions match" detail="Adjust your text or category filters, or start a thread."/>}</section>}
    {(metricId||algoId||discussionId)&&<div className="comments-drawer panel"><div className="section-title"><div><div className="eyebrow">THREAD</div><h3>Comments</h3></div><button className="icon-button" onClick={closeComments} aria-label="Close comments" data-testid="button-close-thread"><X size={15}/></button></div>{activeComments?.length?activeComments.map((c:any)=><div className="comment-row" key={c.id}><strong>{c.authorName}</strong><span>{c.message}</span><small>{dateLabel(c.createdAt)}</small></div>):<p className="muted small">No replies yet. Add the first useful note.</p>}<form className="comment-entry" onSubmit={submitComment}><input className="field" value={message} onChange={e=>setMessage(e.target.value)} placeholder="Add context or ask a follow-up…" data-testid="input-community-comment"/><button className="action-btn primary-btn" disabled={!message.trim()} data-testid="button-submit-community-comment">Post reply</button></form></div>}
  </div></Shell>;
}

function Router() { return <Switch><Route path="/" component={Dashboard}/><Route path="/simulator" component={Simulator}/><Route path="/analytics" component={Analytics}/><Route path="/community" component={Community}/><Route component={NotFound}/></Switch>; }
function App() { return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><Router/></WouterRouter></QueryClientProvider>; }
export default App;
